INSERT INTO truss.prop_def(prop_id,type_id,element,name,scalar_type,nullability,cardinality,home,since_rev,doc_ord,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id) VALUES((SELECT maximum_id::bigint+2 FROM pg_temp.ashlar_probe_high_water WHERE allocation_domain='prop_id'),1,pg_catalog.convert_from(pg_catalog.decode('6c6162656c','hex'),'UTF8'),pg_catalog.convert_from(pg_catalog.decode('6c6162656c','hex'),'UTF8'),'string',pg_catalog.convert_from(pg_catalog.decode('7265717569726564','hex'),'UTF8'),'one','json',1,0,'accepted_document',1,0,pg_catalog.convert_from(pg_catalog.decode('74727573732d776566742d736f757263652d7265766965772d66697874757265','hex'),'UTF8'));
INSERT INTO truss.prop_def(prop_id,type_id,element,name,scalar_type,nullability,cardinality,home,since_rev,doc_ord,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id) VALUES((SELECT maximum_id::bigint+1 FROM pg_temp.ashlar_probe_high_water WHERE allocation_domain='prop_id'),1,pg_catalog.convert_from(pg_catalog.decode('63617074696f6e','hex'),'UTF8'),pg_catalog.convert_from(pg_catalog.decode('63617074696f6e','hex'),'UTF8'),'string',pg_catalog.convert_from(pg_catalog.decode('616273656e742d616c6c6f776564','hex'),'UTF8'),'one','json',1,0,'accepted_document',1,0,pg_catalog.convert_from(pg_catalog.decode('74727573732d776566742d736f757263652d7265766965772d66697874757265','hex'),'UTF8'));
SELECT json_build_object('phase','candidate','head',(SELECT rev FROM truss.schema_head WHERE id=1),
      'original_request',(SELECT origin FROM truss.schema_rev WHERE rev=1),
      'document',(SELECT json_build_object('doc_id',doc_id,'doc_revision',doc_revision,'umf_version',umf_version,'content_sha256',content_sha256,'document',document,'validation',validation) FROM truss.schema_doc WHERE rev=1),
      'types',(SELECT coalesce(json_agg(row_to_json(t) ORDER BY type_id),'[]'::json) FROM
        (SELECT document_id,type_id,module,element,kind,since_rev,doc_ord,retired_rev,provisional,lineage_profile,encode(lineage_bytes,'hex') lineage_hex,encode(lineage_sha256,'hex') lineage_sha256,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id,binding_source_rev,binding_source_pointer,binding_source_bytes FROM truss.type_def) t),
      'properties',(SELECT coalesce(json_agg(row_to_json(p) ORDER BY prop_id),'[]'::json) FROM
        (SELECT prop_id,type_id,element,name,scalar_type,nullability,cardinality,home,since_rev,doc_ord,retired_rev,facets,item,definition_source_kind,definition_rev,definition_doc_ord,definition_document_id,binding_source_rev,binding_source_pointer,binding_source_bytes FROM truss.prop_def) p),
      'report_count',(SELECT count(*) FROM truss.catalog_acceptance_report));
      ROLLBACK;
      SELECT json_build_object('phase','after_rollback','head',(SELECT rev FROM truss.schema_head WHERE id=1),
        'revision_count',(SELECT count(*) FROM truss.schema_rev),'document_count',(SELECT count(*) FROM truss.schema_doc),
        'type_count',(SELECT count(*) FROM truss.type_def),'property_count',(SELECT count(*) FROM truss.prop_def),
        'report_count',(SELECT count(*) FROM truss.catalog_acceptance_report));
